/* Bootstrap 5.3 Minimal JS - Essential Interactions */
(function(){var t=document.querySelectorAll('[data-bs-toggle="collapse"]');t.forEach(function(e){e.addEventListener('click',function(n){n.preventDefault();var i=document.querySelector(this.getAttribute('data-bs-target'));i&&(i.classList.contains('show')?i.classList.remove('show'):i.classList.add('show'))})})})();
